import Foundation
import SpriteKit

/// One of the four SpriteWorld wall-sheet families used by the original game.
/// Raw values intentionally match `_drawMazePiece`'s recovered type values 0...3.
enum AquaDotOriginalSolidWallAtlasType: Int, CaseIterable, Sendable {
    case nineByNine = 0
    case tenByNine = 1
    case nineByTen = 2
    case tenByTen = 3

    var assetSuffix: String {
        switch self {
        case .nineByNine: return "9x9"
        case .tenByNine: return "10x9"
        case .nineByTen: return "9x10"
        case .tenByTen: return "10x10"
        }
    }

    var sheetPixelSize: CGSize {
        switch self {
        case .nineByNine: return CGSize(width: 180, height: 180)
        case .tenByNine: return CGSize(width: 200, height: 225)
        case .nineByTen: return CGSize(width: 180, height: 250)
        case .tenByTen: return CGSize(width: 200, height: 1150)
        }
    }

    fileprivate var baseFrameSize: CGSize {
        switch self {
        case .nineByNine: return CGSize(width: 9, height: 9)
        case .tenByNine: return CGSize(width: 10, height: 9)
        case .nineByTen: return CGSize(width: 9, height: 10)
        case .tenByTen: return CGSize(width: 10, height: 10)
        }
    }

    /// `SWCreateSpriteFromSingleFileXY` receives the inter-frame gaps 36/40.
    /// Its 0x40 option centers the small frame inside that gap, so the first
    /// source frame begins at half the gap and the next frame advances by
    /// `baseSize + gap`.
    fileprivate var frameGap: CGSize {
        switch self {
        case .nineByNine: return CGSize(width: 36, height: 36)
        case .tenByNine: return CGSize(width: 40, height: 36)
        case .nineByTen: return CGSize(width: 36, height: 40)
        case .tenByTen: return CGSize(width: 40, height: 40)
        }
    }
}

struct AquaDotOriginalSolidWallPiece: Equatable, Sendable {
    let atlasType: AquaDotOriginalSolidWallAtlasType
    let frameIndex: Int
}

struct AquaDotOriginalSolidWallSelection: Equatable, Sendable {
    /// `_drawMazePiece` iterates these clockwise: TL, TR, BR, BL.
    let pieces: [AquaDotOriginalSolidWallPiece]
}

/// Exact selector-state bridge recovered from the i386 `_loadMaze` decision tree.
