//////8=
"""
        guard let data = Data(base64Encoded: encoded, options: .ignoreUnknownCharacters) else {
            preconditionFailure("Phase 4A selector lookup table could not be decoded")
        }
        return Array(data)
    }()

    static func selection(forFlagKey key: UInt16) -> AquaDotOriginalSolidWallSelection? {
        let offset = Int(key) * 5
        guard offset + 4 < table.count else { return nil }

        var packed: UInt64 = 0
        for byteIndex in 0..<5 {
            packed |= UInt64(table[offset + byteIndex]) << (byteIndex * 8)
        }
        if packed == 0xFF_FF_FF_FF_FF { return nil }

        var pieces: [AquaDotOriginalSolidWallPiece] = []
        pieces.reserveCapacity(4)
        for quadrant in 0..<4 {
            let shift = quadrant * 9
            let typeRaw = Int((packed >> UInt64(shift)) & 0x3)
            let frame = Int((packed >> UInt64(shift + 2)) & 0x7F)
            guard let atlasType = AquaDotOriginalSolidWallAtlasType(rawValue: typeRaw) else {
                return nil
            }
            pieces.append(AquaDotOriginalSolidWallPiece(atlasType: atlasType, frameIndex: frame))
        }
        return AquaDotOriginalSolidWallSelection(pieces: pieces)
    }

    static func selection(
        x: Int,
        y: Int,
        rawCells: [GridPosition: UInt8]
    ) -> AquaDotOriginalSolidWallSelection? {
        func raw(_ dx: Int, _ dy: Int) -> UInt8 {
            rawCells[GridPosition(x: x + dx, y: y + dy)] ?? 0
        }

        let west = raw(-1, 0)
        let east = raw(1, 0)
        let north = raw(0, -1)
        let south = raw(0, 1)
        let northWest = raw(-1, -1)
        let southWest = raw(-1, 1)
        let northEast = raw(1, -1)
        let southEast = raw(1, 1)

        @inline(__always) func solid(_ value: UInt8) -> Bool { value == 0x10 }
        @inline(__always) func has(_ value: UInt8, _ mask: UInt8) -> Bool {
            value != 0x10 && (value & mask) != 0
        }

        // Bit order is the exact order used by the exhaustive i386 selector emulator:
        // W E N S NW SW NE SE e7 e6 e3 e2 df de db da.
        var key: UInt16 = 0
        @inline(__always) func set(_ bit: Int, _ value: Bool) {
            if value { key |= UInt16(1 << bit) }
        }

        set(0, solid(west))
        set(1, solid(east))
        set(2, solid(north))
        set(3, solid(south))
        set(4, solid(northWest))
        set(5, solid(southWest))
        set(6, solid(northEast))
        set(7, solid(southEast))

        set(8,  has(west, 0x04) || has(northWest, 0x01))
        set(9,  has(north, 0x08) || has(northWest, 0x02))
        set(10, has(west, 0x01) || has(southWest, 0x04))
        set(11, has(south, 0x08) || has(southWest, 0x02))
        set(12, has(east, 0x04) || has(northEast, 0x01))
        set(13, has(north, 0x02) || has(northEast, 0x08))
        set(14, has(east, 0x01) || has(southEast, 0x04))
        set(15, has(south, 0x02) || has(southEast, 0x08))

        return selection(forFlagKey: key)
    }
}

/// Replays the original `_drawMazePiece` frame selection and destination-rectangle
/// behavior using the preserved 13 wall material sheets. Remastered rendering is
/// deliberately not routed through this class.
final class AquaDotOriginalSolidWallRenderer {
    private let themeIndex: Int
    private let material: AquaDotWallMaterial
    private let atlases: [AquaDotOriginalSolidWallAtlasType: SKTexture]

    init(themeIndex: Int, material: AquaDotWallMaterial) {
        self.themeIndex = max(1, min(13, themeIndex))
        self.material = material

        var loaded: [AquaDotOriginalSolidWallAtlasType: SKTexture] = [:]
        for type in AquaDotOriginalSolidWallAtlasType.allCases {
            let name = String(format: "P4A_SolidWall_%02d_", self.themeIndex)
                + type.assetSuffix
                + "_Original"
            let texture = SKTexture(imageNamed: name)
            texture.filteringMode = .nearest
            loaded[type] = texture
        }
        self.atlases = loaded
    }

    /// Returns false without drawing anything if a malformed/custom maze produces
    /// a selector state the historical routine did not initialize. The caller can
    /// then use the existing defensive procedural fallback instead of crashing.
    @discardableResult
    func render(
        cells: [AquaDotWallCell],
        layout: AquaDotMazeLayout,
        into root: SKNode
    ) -> Bool {
        var rawCells: [GridPosition: UInt8] = [:]
        rawCells.reserveCapacity(cells.count)
        for cell in cells {
            rawCells[GridPosition(x: cell.x, y: cell.y)] = Self.rawValue(for: cell.kind)
        }

        // Preserve `_loadMaze` row-major traversal and `_drawMazePiece`'s quadrant
        // order because oversized pieces can overlap. We preflight all selections
        // first so the fallback path never leaves a half-rendered historical layer.
        var jobs: [(AquaDotWallCell, AquaDotOriginalSolidWallSelection)] = []
        for cell in cells {
            guard case .blocked = cell.kind else { continue }
            guard let selection = AquaDotOriginalSolidWallSelector.selection(
                x: cell.x,
                y: cell.y,
                rawCells: rawCells
            ) else {
                return false
            }
            jobs.append((cell, selection))
        }

        // `_drawMazePiece` multiplies maze coordinates by the recovered 18.0-pixel
        // pitch. Revival's scene layout currently spaces gameplay at 20 points, so
        // preserve the historical wall geometry by scaling every recovered pixel
        // offset uniformly into the active layout rather than mutating simulation.
        let pixelScale = layout.pitch / 18.0
        var drawOrdinal: CGFloat = 0

        for (cell, selection) in jobs {
            let center = layout.wallCellCenter(x: cell.x, y: cell.y)
            let topLeft = CGPoint(
                x: center.x - layout.pitch * 0.5,
                y: center.y + layout.pitch * 0.5
            )

            for quadrant in 0..<4 {
                let piece = selection.pieces[quadrant]
                guard let atlas = atlases[piece.atlasType] else { return false }
                let source = Self.sourcePixelRect(
                    atlasType: piece.atlasType,
                    frameIndex: piece.frameIndex
                )
                let destination = Self.destinationPixelRect(
                    atlasType: piece.atlasType,
                    frameIndex: piece.frameIndex,
                    quadrant: quadrant
                )

                let sheet = piece.atlasType.sheetPixelSize
                let normalized = CGRect(
                    x: source.minX / sheet.width,
                    y: 1.0 - (source.maxY / sheet.height),
                    width: source.width / sheet.width,
                    height: source.height / sheet.height
                )
                let texture = SKTexture(rect: normalized, in: atlas)
                texture.filteringMode = .nearest

                let node = SKSpriteNode(texture: texture)
                node.name = "original-solid-wall-\(cell.x)-\(cell.y)-q\(quadrant)-t\(piece.atlasType.rawValue)-f\(piece.frameIndex)"
                node.size = CGSize(
                    width: destination.width * pixelScale,
                    height: destination.height * pixelScale
                )
                node.position = CGPoint(
                    x: topLeft.x + destination.midX * pixelScale,
                    y: topLeft.y - destination.midY * pixelScale
                )

                // The preserved wall sheets are grayscale material/light maps; the
                // historical code applies color separately. Exact legacy color math
                // is still outside Phase 4A, so retain Revival's current palette tint
                // while preserving the recovered source pixels and alpha exactly.
                node.color = material.body
                node.colorBlendFactor = 0.76

                // SpriteView uses ignoresSiblingOrder. Tiny monotonic z increments
                // reproduce the bitmap-era row-major + quadrant blit order without
                // colliding with the numeric-wall z=2 layer.
                node.zPosition = 1.0 + drawOrdinal * 0.000001
                drawOrdinal += 1
                root.addChild(node)
            }
        }
        return true
    }

    nonisolated static func sourcePixelRect(
        atlasType: AquaDotOriginalSolidWallAtlasType,
        frameIndex: Int
    ) -> CGRect {
        let base = atlasType.baseFrameSize
        let gap = atlasType.frameGap
        let stepX = base.width + gap.width
        let stepY = base.height + gap.height

        // The SpriteWorld 0x40 creation option centers the frame in each gap.
        var left = gap.width * 0.5 + CGFloat(frameIndex % 4) * stepX
        var top = gap.height * 0.5 + CGFloat(frameIndex / 4) * stepY
        var right = left + base.width
        var bottom = top + base.height

        // `_loadMazeWalls` mutates selected SpriteWorld frame source rects after
        // loading. These are the exact index ranges and +/-10 pixel mutations.
        switch atlasType {
        case .nineByNine:
            break
        case .tenByNine:
            if (8...9).contains(frameIndex) {
                right += 10
            } else if (10...11).contains(frameIndex) {
                left -= 10
            }
        case .nineByTen:
            if (8...9).contains(frameIndex) {
                top -= 10
            } else if (10...11).contains(frameIndex) {
                bottom += 10
            }
        case .tenByTen:
            if (4...19).contains(frameIndex) {
                left -= 10; top -= 10
            } else if (24...39).contains(frameIndex) {
                right += 10; top -= 10
            } else if (44...59).contains(frameIndex) {
                right += 10; bottom += 10
            } else if (64...79).contains(frameIndex) {
                left -= 10; bottom += 10
            }
        }
        return CGRect(x: left, y: top, width: right - left, height: bottom - top)
    }

    nonisolated static func destinationPixelRect(
        atlasType: AquaDotOriginalSolidWallAtlasType,
        frameIndex: Int,
        quadrant: Int
    ) -> CGRect {
        // `_drawMazePiece` walks TL, TR, BR, BL.
        let qx: CGFloat = (quadrant == 1 || quadrant == 2) ? 1 : 0
        let qy: CGFloat = (quadrant >= 2) ? 1 : 0

        var baseX: CGFloat = 0
        var baseY: CGFloat = 0
        var width = atlasType.baseFrameSize.width
        var height = atlasType.baseFrameSize.height

        switch atlasType {
        case .nineByNine:
            break
        case .tenByNine:
            baseX -= 1
            if (8...11).contains(frameIndex) {
                baseX -= 10
                width = 20
            }
        case .nineByTen:
            baseY -= 1
            if (8...11).contains(frameIndex) {
                baseY -= 10
                height = 20
            }
        case .tenByTen:
            baseX -= 1
            baseY -= 1
            if (4...19).contains(frameIndex)
                || (24...39).contains(frameIndex)
                || (44...59).contains(frameIndex)
                || (64...79).contains(frameIndex) {
                baseX -= 10
                baseY -= 10
                width = 20
                height = 20
            }
        }

        return CGRect(
            x: baseX + qx * width,
            y: baseY + qy * height,
            width: width,
            height: height
        )
    }

    private static func rawValue(for kind: AquaDotWallCell.Kind) -> UInt8 {
        switch kind {
        case .blocked: return 0x10
        case let .wall(geometry): return geometry.rawValue
        case .open, .wrapBoundary, .unknown: return 0
        }
    }
}
